export const TREND_OPTIONS = (type) => {
  const options = {
    tooltip: {
      trigger: 'axis',
      formatter: (params) => {
        let tip = params[0].name + '<br>'
        for (let i = 0; i < params.length; i++) {
          tip += params[i].marker + params[i].seriesName + ': ' + Number(params[i].value).toFixed(2) + '<br>'
        }
        return tip
      }
    },
    color: trendPageType[type].color,
    legend: {
      top: '3%',
      data: trendPageType[type].legendData,
      itemWidth: 18,
      itemHeight: 12,
      textStyle: { color: '#000', fontSize: 12 }
    },
    grid: {
      left: '2%',
      right: '3%',
      bottom: '10%',
      top: '12%',
      containLabel: true
    },
    xAxis: {
      type: 'category',
      boundaryGap: false,
      data: trendPageType[type].date,
      axisLabel: {
        inside: false,
        textStyle: {
          fontSize: 11
        }
      },
      axisLine: {
        show: false
      },
      axisTick: {
        show: false
      },
      splitArea: {
        show: true,
        areaStyle: {
          color: ['rgba(250,250,250,0.3)', 'rgba(255,255,255,0.3)']
        }
      },
      splitLine: {
        show: true,
        lineStyle: {
          color: '#e5e5e5',
          type: 'dashed'
        }
      }
    },
    yAxis: [
      {
        type: 'value',
        position: 'left',
        axisLabel: {},
        axisLine: {
          show: false
        },
        axisTick: {
          show: false
        },
        splitArea: {
          show: false
        },
        splitLine: {
          show: true,
          lineStyle: {
            color: '#e5e5e5',
            type: 'dashed'
          }
        }
      },
      {
        axisLine: {
          show: false
        },
        axisTick: {
          show: false
        },
        splitLine: {
          show: false
        },
        type: 'value',
        splitNumber: 3,
        axisLabel: {
          formatter: '{value}'
        }
      }
    ],
    dataZoom: {
      show: true,
      start: 0,
      end: 20,
      maxSpan: 80,
      textStyle: {
        color: 'transparent'
      }
    },
    series: trendPageType[type].series
  }
  return options
}
